{
  "dashboard": {
    "id": null,
    "uid": "enterprise-observability-dashboard",
    "title": "Enterprise Observability Overview",
    "tags": ["enterprise", "observability", "overview"],
    "timezone": "browser",
    "schemaVersion": 38,
    "version": 1,
    "refresh": "30s",
    "templating": {
      "list": [
        {
          "name": "datasource",
          "type": "datasource",
          "pluginId": "prometheus",
          "label": "Prometheus"
        },
        {
          "name": "environment",
          "type": "custom",
          "query": "production,staging,development",
          "label": "Environment",
          "multi": false,
          "includeAll": false
        }
      ]
    },
    "panels": [
      {
        "type": "stat",
        "title": "Overall System Health",
        "gridPos": {
          "h": 6,
          "w": 4,
          "x": 0,
          "y": 0
        },
        "targets": [
          {
            "expr": "sum(up{job=~\"$job\"}) / count(up{job=~\"$job\"}) * 100",
            "instant": true,
            "refId": "A"
          }
        ],
        "options": {
          "orientation": "auto",
          "textMode": "value_and_name",
          "colorMode": "background",
          "graphMode": "none",
          "justifyMode": "auto"
        },
        "fieldConfig": {
          "defaults": {
            "unit": "percent",
            "thresholds": {
              "mode": "absolute",
              "steps": [
                { "color": "red", "value": null },
                { "color": "orange", "value": 80 },
                { "color": "green", "value": 95 }
              ]
            }
          }
        }
      },
      {
        "type": "timeseries",
        "title": "Request Rate by Service",
        "gridPos": {
          "h": 8,
          "w": 12,
          "x": 4,
          "y": 0
        },
        "targets": [
          {
            "expr": "sum(rate(http_requests_total{environment=\"$environment\"}[5m])) by (service)",
            "legendFormat": "{{service}}",
            "refId": "A"
          }
        ],
        "options": {
          "tooltip": {
            "mode": "multi",
            "sort": "desc"
          }
        },
        "fieldConfig": {
          "defaults": {
            "unit": "req/s"
          }
        }
      },
      {
        "type": "heatmap",
        "title": "Response Time Distribution",
        "gridPos": {
          "h": 8,
          "w": 8,
          "x": 16,
          "y": 0
        },
        "targets": [
          {
            "expr": "http_request_duration_seconds_bucket{environment=\"$environment\"}",
            "format": "heatmap",
            "legendFormat": "{{le}}",
            "refId": "A"
          }
        ],
        "options": {
          "calculate": false,
          "color": {
            "exponent": 0.5,
            "fill": "dark-orange",
            "mode": "scheme",
            "reverse": false,
            "scale": "exponential",
            "scheme": "Oranges",
            "steps": 64
          }
        }
      }
    ]
  }
}
